head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Workflow > P > resolveCallback]<br/>Workflow 모듈의 모든 작업이 정상적으로 완료된 다음 실행할 콜백 함수를 설정합니다.",
    "validation" : [
        "Workflow 모듈이 정상적으로 완료되었을 때 실행할 콜백 함수를 설정할 수 있어야 합니다.",
        "콜백 함수에는 Workflow 객체가 파라미터로 전달되어야 합니다.",
        "Workflow 의 모든 작업이 중도 거부나 예외 없이 이행된 경우에만 콜백 함수가 1 회 실행되어야 합니다."
    ]
}

scwin.gVar = {
    "count" : {},
    "param" : {},
    "stepAfter" : 0
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 페이지 scope 적용으로 Workflow 객체의 id 에는 prefix 가 붙으므로 짧은 ID 로 변환
scwin.getShortId = function (fullId) {
    var s = String(fullId);
    if (s.indexOf("wf_nocb") > -1) return "wf_nocb";
    if (s.indexOf("wf_reject") > -1) return "wf_reject";
    return "wf_ok";
};

// 집계 초기화
scwin.resetCount = function () {
    scwin.gVar.count = {};
    scwin.gVar.param = {};
    scwin.gVar.stepAfter = 0;
};



// wf_ok / wf_nocb 의 마지막 function step
scwin.wf_step_function = function (prevResult, wObj) {
};

// wf_reject 의 function step - 진행 중인 Workflow 를 중도 거부
scwin.wf_step_reject = function (prevResult, wObj) {
    wObj.reject("중도 거부");
};

// wf_reject 의 마지막 function step - 중도 거부되었으므로 실행되지 않아야 함
scwin.wf_step_after = function (prevResult, wObj) {
    scwin.gVar.stepAfter++;
};

// 검증 대상 - resolveCallback 으로 설정한 콜백 함수
scwin.wf_resolveCallback = function (wObj) {
    var key = scwin.getShortId(wObj && wObj.id);
    scwin.gVar.count[key] = (scwin.gVar.count[key] || 0) + 1;
    scwin.gVar.param[key] = {
        "type" : (typeof wObj),
        "id" : (wObj && wObj.id) ? wObj.id : "-"
    };
};



// (1) resolveCallback 설정 Workflow 와 미설정 Workflow 를 각각 실행하여 콜백 설정 여부 확인
scwin.btn_executeResolve_onclick = async function () {
    scwin.resetCount();
    await $p.executeWorkflow("wf_ok");
    await $p.executeWorkflow("wf_nocb");
    await new Promise(function (r) { setTimeout(r, 500); });
    wf_body_bottom.getObj("scwin").setReturnValue("[콜백 설정] wf_ok(resolveCallback 설정) 콜백 실행 횟수 : " + (scwin.gVar.count["wf_ok"] || 0) + " / wf_nocb(resolveCallback 미설정) : " + (scwin.gVar.count["wf_nocb"] || 0));
};

// (2) 콜백 함수가 전달받은 파라미터 확인
scwin.btn_checkParam_onclick = async function () {
    scwin.resetCount();
    await $p.executeWorkflow("wf_ok");
    await new Promise(function (r) { setTimeout(r, 500); });
    var p = scwin.gVar.param["wf_ok"] || { "type" : "-", "id" : "-" };
    wf_body_bottom.getObj("scwin").setReturnValue("[전달 파라미터] 콜백 파라미터 타입 : " + p.type + " / 파라미터의 id : " + p.id + " / 실행한 Workflow 의 id : " + $p.getWorkflow("wf_ok").id);
};

// (3) 정상 완료 Workflow 와 중도 거부 Workflow 의 콜백 실행 횟수 확인
scwin.btn_checkCallCount_onclick = async function () {
    scwin.resetCount();
    await $p.executeWorkflow("wf_ok");
    await $p.executeWorkflow("wf_reject");
    await new Promise(function (r) { setTimeout(r, 1000); });
    wf_body_bottom.getObj("scwin").setReturnValue("[호출 횟수] 정상 완료 wf_ok : " + (scwin.gVar.count["wf_ok"] || 0) + " 회 / 중도 거부 wf_reject : " + (scwin.gVar.count["wf_reject"] || 0) + " 회");
};
